package com.credvenn.lm.applicationvariable;
import com.credvenn.lm.common.domain.AuditableEntity;import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="application_variables") public class ApplicationVariable extends AuditableEntity{@Id @Column(length=36)String id;@Column(name="tenant_id",nullable=false)String tenantId;@Column(name="application_id",nullable=false)String applicationId;@Column(name="definition_id",nullable=false)String definitionId;@Column(name="code_snapshot",nullable=false)String code;@Column(name="label_snapshot",nullable=false)String label;@Column(name="section_snapshot")String section;@Enumerated(EnumType.STRING)@Column(name="field_type_snapshot",nullable=false)ApplicationVariableFieldType fieldType;@Column(name="answer_value",nullable=false,columnDefinition="TEXT")String value;@PrePersist void id(){if(id==null)id=UUID.randomUUID().toString();}}
